def retry(func, attempts: int = 3, delay: int = 1):
    """
    Execute func with automatic retry on exception.

    Args:
        func: Callable to execute
        attempts: Number of attempts (default: 3)
        delay: Seconds to sleep between attempts (default: 1)

    Returns:
        Result from func on successful attempt

    Raises:
        Exception: Last exception if all attempts fail
    """
    for attempt in range(1, attempts + 1):
        try:
            return func()
        except Exception:
            if attempt < attempts:
                import time
                time.sleep(delay)
            raise
"}

