{"filePath":"/home/dev/project/src/app/retry.py","content":"from typing import Callable, Type, Any, Union


def retry(func: Callable[..., Any], attempts: int, delay: Union[int, float]) -> Callable[..., Any]:
    """
    Retry decorator that calls the function with exception handling.

    Args:
        func: The function to call with retry logic.
        attempts: Maximum number of attempt to call the function.
        delay: Seconds to wait between attempts.

    Returns:
        The decorated function.
    """
    def wrapper(*args, **kwargs):
        last_exception = None
        for attempt in range(attempts):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                last_exception = e
                if attempt < attempts - 1:
                    import time
                    time.sleep(delay)
        raise last_exception

    return wrapper
"}

